from __future__ import annotations
from collections import Counter
from typing import Dict, Iterable, Tuple
Word = Tuple[int, ...]
def words(n: int) -> Iterable[Word]:
    if n < 0: raise ValueError("n must be nonnegative")
    for x in range(1 << n):
        yield tuple((x >> j) & 1 for j in reversed(range(n)))
def class_sizes(n: int) -> Dict[Word, int]:
    return dict(Counter(w for w in words(n) for _decoration in (0, 1)))
if __name__ == "__main__":
    for n in range(9):
        sizes = class_sizes(n)
        print(n, 2 ** (n + 1), len(sizes), set(sizes.values()))

from __future__ import annotations
from math import cos, pi
from typing import List, Tuple
def gram_entries(max_order: int) -> List[Tuple[int, float]]:
    if max_order < 2: raise ValueError("max_order must be at least 2")
    return [(m, -cos(pi / m)) for m in range(2, max_order + 1)]
if __name__ == "__main__":
    for m, g in gram_entries(20):
        assert -1.0 < g <= 1e-15
        print(f"m={m:2d}, entry={g:.12f}")

from __future__ import annotations
from math import exp, log
from typing import List, Tuple
def growth_table(max_n: int, a: float, b: float) -> List[Tuple[int, float, int, float]]:
    if max_n < 0 or a <= 0 or b < 0: raise ValueError("invalid parameters")
    return [(n, a*n+b, 2**n, exp((log(2)/a)*((a*n+b)-b))) for n in range(max_n+1)]
if __name__ == "__main__":
    for row in growth_table(16, 2.5, 3.0): print(row)

